import os

SRC = "/data/legacy"
DST = "/out/clean"
MANIFEST = "/out/manifest.tsv"

def detect_and_decode(raw: bytes):
    if raw.startswith(b"\xff\xfe") or raw.startswith(b"\xfe\xff"):
        return "utf-16", raw.decode("utf-16")  # codec strips BOM
    if raw.startswith(b"\xef\xbb\xbf"):
        return "utf-8-sig", raw.decode("utf-8-sig")  # strips BOM
    try:
        return "utf-8", raw.decode("utf-8")
    except UnicodeDecodeError:
        return "latin-1", raw.decode("latin-1")

def normalize(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    if not text.endswith("\n"):
        text += "\n"
    return text

rows = []
for name in sorted(os.listdir(SRC)):
    if not name.endswith(".txt"):
        continue
    path = os.path.join(SRC, name)
    if not os.path.isfile(path):
        continue
    with open(path, "rb") as fh:
        raw = fh.read()
    enc, text = detect_and_decode(raw)
    norm = normalize(text)
    with open(os.path.join(DST, name), "wb") as fh:
        fh.write(norm.encode("utf-8"))  # utf-8, no BOM
    rows.append((name, enc, norm.count("\n"), len(norm)))

with open(MANIFEST, "w", encoding="utf-8", newline="") as fh:
    fh.write("name\tencoding\tlines\tchars\n")
    for r in rows:
        fh.write("%s\t%s\t%d\t%d\n" % r)

print("processed:", [r[0] for r in rows])
EOF
python3 /tmp/clean.py

